ruleContent.content:
@js:
var startMark = '<!-- #d蛋文开 -->';
var endMark = '<!-- #d蛋文结 -->';
var a = src.indexOf(startMark);
var b = src.indexOf(endMark);
var c = a >= 0 && b > a ? src.substring(a + startMark.length, b) : '';

var nl = String.fromCharCode(10);
c = c.split('<br/>').join(nl);
c = c.split('<br>').join(nl);
c = c.split('<BR>').join(nl);
c = c.split('&nbsp;').join(' ');
c = c.replaceAll('<[^>]+>', '');

// 去掉开头的多余换行
c = c.replace(/^\n+/, '');

c;

ruleToc.chapterList:
@js:
var m = src.match(/<b>(\d+)<\/b>\s*\/\s*<b>(\d+)<\/b>/);
var total = m ? parseInt(m[2]) : 1;
var base = baseUrl.replace('.html', '');
var arr = [];
for (var i = 1; i <= total; i++) {
  arr.push({
    title: '第' + i + '页',
    url: base + (i == 1 ? '.html' : '_' + i + '.html')
  });
}
arr;

